    'Affects speech only — images and transcription stay on the endpoint above.': 'Afecta solo a la voz — la imagen y la transcripción siguen usando el endpoint de arriba.',
    'ElevenLabs API Key': 'Clave API de ElevenLabs',
    '(saved)': '(guardada)',
    'Stored encrypted, like the OpenAI key. Save the key first, then assign voices below.': 'Se guarda cifrada, como la clave de OpenAI. Guarda la clave primero y luego asigna las voces abajo.',
    'eleven_multilingual_v2 has the best quality for single words; flash/turbo are cheaper and can enforce Spanish via language code.': 'eleven_multilingual_v2 tiene la mejor calidad para palabras sueltas; flash/turbo son más baratos y pueden forzar el español mediante código de idioma.',
    'Accent voices': 'Voces por acento',
    'Save an ElevenLabs API key first — then your account’s voices appear here for mapping.': 'Guarda primero una clave API de ElevenLabs — después las voces de tu cuenta aparecerán aquí para asignarlas.',
    'Loading voices…': 'Cargando voces…',
