    'AI is paused — the provider account is out of credit.': 'La IA está en pausa — la cuenta del proveedor no tiene crédito.',
    'paused since': 'en pausa desde',
    'Requests stop automatically so students are not left retrying. Add credit, then it resumes on its own.': 'Las solicitudes se detienen automáticamente para que los estudiantes no sigan reintentando. Añade crédito y se reanudará solo.',
    'Makes this deck brand new again — clears scheduling and review history. Cards and audio are kept.': 'Deja este mazo como nuevo — borra la programación y el historial de repasos. Las tarjetas y el audio se conservan.',
