    'Reset progress on “{{deck}}” for {{who}}? Review history will be deleted.': '¿Reiniciar el progreso de «{{deck}}» para {{who}}? Se borrará el historial de repasos.',
    'Turn off a side to skip generating its audio — its play button disappears too.': 'Desactiva un lado para no generar su audio — su botón de reproducción también desaparece.',
