    'Play a short sample with this voice': 'Reproducir una muestra corta con esta voz',
    'Voice preview failed — the voice may be broken or removed from your account.': 'La prueba de voz falló — la voz puede estar dañada o eliminada de tu cuenta.',
    '— use default voice —': '— usar la voz predeterminada —',
    'A default voice is required — speech generation fails without one.': 'Se requiere una voz predeterminada — sin ella la generación de voz falla.',
    'Refreshing…': 'Actualizando…',
    'This ID is not in the provider’s current model list — double-check it before saving (a typo breaks all audio generation).': 'Este ID no está en la lista actual de modelos del proveedor — revísalo antes de guardar (un error tipográfico rompe toda la generación de audio).',
    'Must be a model on OpenAI’s /v1/audio/speech endpoint (the gpt-4o-mini-tts family or tts-1/tts-1-hd). Only gpt-4o-mini-tts models honor the pronunciation instructions.': 'Debe ser un modelo del endpoint /v1/audio/speech de OpenAI (la familia gpt-4o-mini-tts o tts-1/tts-1-hd). Solo los modelos gpt-4o-mini-tts respetan las instrucciones de pronunciación.',
    'Each word is played in a randomly chosen accent — tests comprehension across dialects. Generate clips for several accents below first.': 'Cada palabra se reproduce en un acento elegido al azar — evalúa la comprensión entre dialectos. Genera primero clips de varios acentos abajo.',
    'The audio bank for this accent must be generated below before students can take the test.': 'El banco de audio de este acento debe generarse abajo antes de que los estudiantes puedan hacer la prueba.',
    'Audio bank (TTS)': 'Banco de audio (TTS)',
    'Generated clips power the aural test modes. One clip per word and accent; generation uses the configured AI voice and runs in the background.': 'Los clips generados alimentan los modos auditivos. Un clip por palabra y acento; la generación usa la voz de IA configurada y corre en segundo plano.',
    'Generate {{count}} missing clip(s)': 'Generar {{count}} clip(s) pendiente(s)',
    'Generating…': 'Generando…',
    'failed': 'fallidos',
    'Re-generate {{count}} selected': 'Regenerar {{count}} seleccionadas',
    'Re-generate all {{count}} selected clip(s), overwriting existing audio? Use this after changing the accent or to fix mispronounced words.': '¿Regenerar los {{count}} clip(s) seleccionados, sobrescribiendo el audio existente? Úsalo tras cambiar el acento o para corregir palabras mal pronunciadas.',
    'Pseudowords are generated with a stricter “pronounce in Spanish, even invented words” instruction. If some still sound anglicized, re-generate them.': 'Las pseudopalabras se generan con una instrucción más estricta («pronuncia en español, aunque sea una palabra inventada»). Si alguna suena con acento inglés, regénérala.',
