    'Re-generate audio for every sentence, overwriting the clips in this voice?': '¿Volver a generar el audio de todas las frases, sobrescribiendo los clips de esta voz?',
    'Re-generate sentence audio': 'Volver a generar el audio de las frases',
    'Sentences without a clip in this voice are read by the student’s browser voice, which differs from device to device.': 'Las frases sin clip en esta voz las lee la voz del navegador del estudiante, que cambia de un dispositivo a otro.',
    'Sentence audio': 'Audio de las frases',
    'professional clone': 'clon profesional',
    'instant clone': 'clon instantáneo',
    'premade': 'prediseñada',
    'designed voice': 'voz diseñada',
    'Speech is served by OpenAI, so the bank uses its OpenAI clips. Switch the TTS provider to ElevenLabs in Admin → AI to choose a Vocabulómetro voice.': 'La voz la genera OpenAI, así que el banco usa sus clips de OpenAI. Cambia el proveedor de TTS a ElevenLabs en Administración → IA para elegir una voz del Vocabulómetro.',
    'Default AI voice ({{name}})': 'Voz predeterminada de IA ({{name}})',
    'Default AI voice': 'Voz predeterminada de IA',
    'Speaks the default accent and the elicited-imitation sentences; other accents keep their voices from Admin → AI. Only clips made in the current voice are played, so generate the bank again after changing it.': 'Habla el acento predeterminado y las frases de imitación provocada; los demás acentos conservan sus voces de Administración → IA. Solo se reproducen los clips hechos con la voz actual, así que vuelve a generar el banco después de cambiarla.',
    'The student hears each sentence (generated audio in the Vocabulómetro voice; browser speech only for a sentence without a clip) and repeats it aloud; the recording is transcribed and scored. Requires AI (transcription) enabled and student microphone permission. Manage the sentence bank below.': 'El estudiante escucha cada frase (audio generado con la voz del Vocabulómetro; la voz del navegador solo para una frase sin clip) y la repite en voz alta; la grabación se transcribe y se puntúa. Requiere IA (transcripción) activada y permiso de micrófono. Gestiona el banco de frases abajo.',
    'Include flagged attempts in class tables': 'Incluir los intentos marcados en las tablas de la clase',
    'Showing the newest {{shown}} of {{total}} records.': 'Se muestran los {{shown}} registros más recientes de {{total}}.',
    'Show more': 'Mostrar más',
    'Scheduled': 'Programada',
    'Ended': 'Terminada',
    'Opens {{date}}': 'Abre el {{date}}',
    'Ended {{date}}': 'Terminó el {{date}}',
    'Close “{{name}}” for students': 'Cerrar «{{name}}» para los estudiantes',
    'Open “{{name}}” for students': 'Abrir «{{name}}» para los estudiantes',
    'Invalid window': 'Ventana no válida',
    'Closes before it opens': 'Cierra antes de abrir',
    'The closing time must be after the opening time.': 'La hora de cierre debe ser posterior a la de apertura.',

