    'This verb’s yo form is irregular, so the regular pattern doesn’t work here.': 'La forma de yo de este verbo es irregular, así que aquí no sirve el patrón regular.',
    'The stem changes here: that form leaves the change out.': 'Aquí la raíz cambia: esa forma no tiene el cambio.',
    'The stem doesn’t change in this form: the change isn’t in every person.': 'En esta forma la raíz no cambia: el cambio no va en todas las personas.',
    'This form has a spelling change (like c → qu) that keeps its sound.': 'Esta forma tiene un cambio de ortografía (como c → qu) que conserva el sonido.',
    'This verb is irregular here, so the regular pattern doesn’t work.': 'Este verbo es irregular aquí, así que no sirve el patrón regular.',
    'Verbs like gustar take {{pronoun}}, not {{subject}}.': 'Los verbos como gustar llevan {{pronoun}}, no {{subject}}.',
    'Verbs like gustar agree with the thing liked, not with who likes it.': 'Los verbos como gustar concuerdan con lo que gusta, no con la persona a quien le gusta.',
