    // The teacher's Sentences panel and results.
    'Sentences': 'Frases',
    'A “give the form” question can be a sentence with a blank instead of a person label: “Mis primos ___ (vivir) en Lima.” The subject tells the student who. Same questions, same progress; a form with no sentence keeps the label.': 'Una pregunta de “da la forma” puede ser una frase con un espacio en blanco en lugar de una persona: “Mis primos ___ (vivir) en Lima.” El sujeto le dice al estudiante quién. Las mismas preguntas y el mismo progreso; una forma sin frase sigue con la persona.',
    'How questions show who': 'Cómo indican las preguntas quién',
    'Off: the person label': 'Desactivado: la persona',
    'Built-in sentences': 'Frases incluidas',
    'Approved sentences only': 'Solo frases aprobadas',
    'Built-in and approved sentences': 'Frases incluidas y aprobadas',
    'Saved when you press Save.': 'Se guarda al pulsar Guardar.',
    'Measure it (holdback)': 'Medirlo (grupo de control)',
    'For each student, half the verbs show sentences and half the label. The first time a form comes back a week or more after the student first saw it, it is shown either way, at random. Results can then compare the two. Leave it off unless you are measuring.': 'Para cada estudiante, la mitad de los verbos salen en frases y la otra mitad con la persona. La primera vez que una forma vuelve una semana o más después de que el estudiante la vio por primera vez, sale de una manera o de la otra, al azar. Así los resultados pueden comparar las dos. Déjalo desactivado si no estás midiendo.',
    'It needs sentences on: with Off, every question shows the label.': 'Necesita las frases activadas: con Desactivado, todas las preguntas muestran la persona.',
    '{{covered}} of {{cells}} forms have a sentence; {{label}} use the label.': '{{covered}} de {{cells}} formas tienen una frase; {{label}} usan la persona.',
    '{{covered}} of {{cells}} forms have a sentence; 1 uses the label.': '{{covered}} de {{cells}} formas tienen una frase; 1 usa la persona.',
    '(with built-in sentences, once you turn them on)': '(con las frases incluidas, cuando las actives)',
