    'Missed far more often than the same form with other sentences or the label (after 15 answers or more).': 'Falladas mucho más que la misma forma con otras frases o con la persona (después de 15 respuestas o más).',
    'otherwise {{misses}} of {{attempts}}': 'si no, {{misses}} de {{attempts}}',
    'Parked sentences': 'Frases apartadas',
    'With the settings as saved, the checker rejects these, so students never see them. Their forms use other sentences or the label.': 'Con los ajustes guardados, el revisor rechaza estas frases, así que los estudiantes nunca las ven. Sus formas usan otras frases o la persona.',
    'Sentences on since {{date}}. Expect a short dip in delayed accuracy after that: the questions look new, the forms are not.': 'Frases activadas desde el {{date}}. Después puede bajar un poco la precisión diferida: las preguntas parecen nuevas, las formas no.',
