    'That’s the {{person}} form. Ustedes takes the -n form, like ellos and ellas.': 'Esa es la forma de {{person}}. Ustedes lleva la forma en -n, como ellos y ellas.',
    'Not named': 'Sin nombrar',
    'Quiz mastery': 'Dominio en la práctica',
    'Days practised': 'Días de práctica',
