    'of {{n}} answers': 'de {{n}} respuestas',
    '{{s}} s typed': '{{s}} s escrita',
    '{{s}} s choice': '{{s}} s opción múltiple',
    'Quiz mastery: forms the student can produce in the quiz, each right at the top on two different days. Mastered forms come due for review, so this number can go down.': 'Dominio en la práctica: formas que el estudiante sabe producir en la práctica, cada una acertada en el peldaño más alto en dos días distintos. Las formas dominadas vuelven para repasarlas, así que este número puede bajar.',
    'Days practised: school days with a round played to the end, in any conjugation quiz: the last 14 days, and in all.': 'Días de práctica: días de clase con una ronda jugada hasta el final, en cualquier práctica de conjugación: los últimos 14 días, y en total.',
    'Delayed accuracy: answers right on forms the student had not seen for a week or more. It predicts a test better than round scores.': 'Acierto tras una pausa: respuestas correctas en formas que el estudiante no había visto en una semana o más. Predice un examen mejor que las puntuaciones de las rondas.',
    'Median time: seconds to answer on a first try, typed and multiple choice, never more than the time that passed between answers. Students never see a clock.': 'Tiempo mediano: segundos para responder al primer intento, escrita y de opción múltiple, nunca más que el tiempo que pasó entre respuestas. Los estudiantes nunca ven un reloj.',
    'Answer times that didn’t match: the page said an answer took longer than the time that passed, which only an edited request can do.': 'Tiempos de respuesta que no cuadran: la página dijo que una respuesta tardó más que el tiempo que pasó, algo que solo hace una petición modificada.',
    'Very fast: a median under {{typed}} s typed or {{choice}} s multiple choice, over {{tries}} or more first tries.': 'Muy rápido: una mediana de menos de {{typed}} s escrita o {{choice}} s de opción múltiple, en {{tries}} primeros intentos o más.',
    'Common mistakes': 'Errores comunes',
    'No named mistakes yet.': 'Aún no hay errores con nombre.',
    'e.g.': 'p. ej.',
    '{{count}}×': '{{count}}×',
    'Naming the verb is always multiple choice: every typed answer is a conjugated form.': 'Nombrar el verbo es siempre de opción múltiple: toda respuesta escrita es una forma conjugada.',
