    // Speaking in every lab pause (v1.15.0): the student
    'Do it in one sitting: about {{minutes}} minutes. The microphone checks for your voice in each pause; nothing is recorded.': 'Hazlo de una sola vez: unos {{minutes}} minutos. El micrófono comprueba tu voz en cada pausa; no se graba nada.',
    'Answer out loud in at least {{needed}} of the {{total}} pauses for this lab to count.': 'Contesta en voz alta en al menos {{needed}} de las {{total}} pausas para que este laboratorio cuente.',
