    "Go on without the microphone? You answered {{answered}} of the 1 pause needed, so the lab won't count until your teacher checks it.": '¿Seguir sin micrófono? Contestaste {{answered}} de la 1 pausa que hace falta, así que el laboratorio no contará hasta que tu profesor lo revise.',
