    '{{count}} pause(s) are 10 seconds or longer. In the generator labs these are the “write it down” pauses, where students write instead of speaking.': '{{count}} pausa(s) duran 10 segundos o más. En los laboratorios del generador son las pausas de «escríbelo», en las que los estudiantes escriben en vez de hablar.',
